class Bug(Base):
    __tablename__ = "bug"

    id = Column(INTEGER(11), primary_key=True)
    link = Column(String(256))
    status = Column(String(128))
    ci_runs = relationship('CIRun', secondary='ci_run_has_bug', back_populates="bugs")
    data = Column(Text)  # relevant information e.g. test case with a bug etc

    project_id = Column(ForeignKey("project.id", ondelete="CASCADE"), nullable=False, index=True)
    project = relationship("Project", back_populates="bugs")

    def get_data(self):
        try:
            return json.loads(self.data)
        except Exception as e:
            return {}

    def set_data(self, new_data):
        self.data = json.dumps(new_data)

    def to_dict(self, recursion_limit=1):
        ci_runs = []
        if recursion_limit > 0:
            for c_r in self.ci_runs:
                ci_runs.append(c_r.to_dict(recursion_limit - 1))
        else:
            ci_runs = [{"id": ci_r.id, "pipeline_id": ci_r.pipeline_id} for ci_r in self.ci_runs]
        ret_data = {}
        ret_data = {"id": self.id, "link": self.link, "status": self.status, "data": self.get_data()}
        if ci_runs:
            ret_data["ci_runs_affected"] = ci_runs
        return ret_data

    def to_json(self):
        return jsonify(self.to_dict())


