class CIRun(Base):
    __tablename__ = "ci_run"

    id = Column(INTEGER(11), primary_key=True)
    data = Column(Text)
    trigger_type_id = Column(ForeignKey("trigger_type.id"), nullable=False, index=True)
    project_id = Column(ForeignKey("project.id", ondelete="CASCADE"), nullable=False, index=True)
    result_state_id = Column(ForeignKey('result_state.id'), nullable=False, index=True)
    run_by_user = Column(String(256))
    pipeline_id = Column(INTEGER(11), nullable=False)

    result_state = relationship("ResultState", uselist=False)
    project = relationship("Project", uselist=False, back_populates="ci_runs")
    trigger_type = relationship("TriggerType", uselist=False, back_populates="ci_runs")
    report = relationship("Report", back_populates="ci_run", uselist=False)
    test_cases = relationship('TestCase', secondary='ci_run_has_test_case', back_populates="ci_runs",
                              cascade="all,delete", passive_deletes=True)
    bugs = relationship("Bug", secondary="ci_run_has_bug", back_populates="ci_runs")

    def get_data(self):
        try:
            return json.loads(self.data)
        except Exception as e:
            return {}

    def set_data(self, new_data):
        self.data = json.dumps(new_data)

    def to_dict(self, recursion_limit=1):
        bugs = []
        if recursion_limit > 0:
            for b in self.bugs:
                bugs.append(b.to_dict(recursion_limit-1))
        else:
            bugs = [b.id for b in self.bugs]
        return {"id": self.id, "pipeline_id": self.pipeline_id, "data": self.get_data(),
                "trigger_type": self.trigger_type.type, "bugs": bugs}

    def to_json(self):
        return jsonify(self.to_dict())


