class Requirement(Base):
    __tablename__ = "requirement"

    id = Column(INTEGER(11), primary_key=True)
    content = Column(String(128))
    project_id = Column(ForeignKey("project.id", ondelete="CASCADE"), nullable=False, index=True)

    project = relationship("Project", uselist=False, back_populates="requirements")
    tags = relationship("Tag", back_populates="requirements", secondary='requirement_has_tag',
                        cascade="all,delete", passive_deletes=True)
    test_cases = relationship("TestCase", secondary="requirement_has_test_case", back_populates='requirements',
                              cascade="all,delete", passive_deletes=True)

    def to_dict(self, recursion_limit=1):
        tcases = []
        if recursion_limit > 0:
            for tc in self.test_cases:
                tcases.append(tc.to_dict())
        else:
            tcases = [tc.id for tc in self.test_cases]
        tags = []
        for t in self.tags:
            tags.append(t.to_dict())
        return {"id": self.id, "project": {"project_name": self.project.name, "project_id": self.project.id},
                "content": self.content, "tags": tags, "in_test_cases": tcases}

    def to_json(self):
        return jsonify(self.to_dict())


class TestCase(Base):
    __tablename__ = "test_case"

    id = Column(INTEGER(11), primary_key=True)
    test_module_id = Column(ForeignKey("test_module.id", ondelete="CASCADE"), nullable=False, index=True)
    priority_id = Column(ForeignKey("priority.id"), nullable=False, index=True)
    name = Column(String(128), nullable=False)
    description = Column(String(256))
    scenario_name = Column(String(256))
    scenario_content = Column(String(8196))

    priority = relationship("Priority", uselist=False)
    test_module = relationship("TestModule", uselist=False, back_populates="test_cases")
    users_assigned = relationship("User", secondary="user_has_test_case", back_populates="assigned_test_cases",
                                  cascade="all,delete", passive_deletes=True)
    test_steps = relationship("TestStep", back_populates="test_case", cascade="all,delete", passive_deletes=True)
    ci_runs = relationship('CIRun', secondary='ci_run_has_test_case', back_populates="test_cases",
                           cascade="all,delete", passive_deletes=True)
    requirements = relationship('Requirement', secondary="requirement_has_test_case", back_populates='test_cases',
                                cascade="all,delete", passive_deletes=True)

    def to_dict(self):
        tsteps = []
        for step in self.test_steps:
            tsteps.append(step.to_dict())
        return {"id": self.id, "name": self.name, "priority": self.priority.type, "scenario_name": self.scenario_name,
                "steps": tsteps}  # , "story_file_content": self.story_file_content }

    def to_json(self):
        return jsonify(self.to_dict())


