class TestStep(Base):
    __tablename__ = "test_step"

    id = Column(INTEGER(11), primary_key=True)
    content = Column(String(256))
    test_case_id = Column(ForeignKey("test_case.id", ondelete="CASCADE"), nullable=False, index=True)
    test_step_definition_id = Column(ForeignKey("test_step_definition.id", ondelete="CASCADE"), nullable=False,
                                     index=True)
    parameters = Column(String(1024))
    order = Column(INTEGER(), nullable=False)

    test_case = relationship("TestCase", back_populates="test_steps", uselist=False)
    test_step_definition = relationship("TestStepDefinition", uselist=False, back_populates="test_steps")

    def get_params(self):
        try:
            return json.loads(self.parameters)
        except Exception as e:
            return {}

    def set_params(self, new_params):
        self.parameters = json.dumps(new_params)


    def to_dict(self):
        return {"id": self.id, "content": self.content, "order": self.order,
                "definition": self.test_step_definition.to_dict()}

    def to_json(self):
        return jsonify(self.to_dict())


